// Pass current UTC timestamp for downstream tz conversion
const now = new Date();
return [{ json: { nowISO: now.toISOString() } }];

// Data comes from the User preferences node
const prefs = $('User preferences').first().json;
const user = $('Loop Users').first().json;

let topicsArray = [];
if (Array.isArray(prefs.topics)) {
  topicsArray = prefs.topics;
} else if (typeof prefs.topics === 'string') {
  topicsArray = prefs.topics.replace(/^{|}$/g, '').split(',').map(t => t.trim()).filter(Boolean);
} else {
  topicsArray = ["news"];
}

if (topicsArray.length === 0) {
  topicsArray = ["news"];
}

return [{
  json: {
    user_id: user.id,
    username: user.username,
    email: user.email,
    topics: topicsArray,
    language: prefs.language || 'fr',
    num_articles: prefs.num_articles || 5,
    custom_prompt: prefs.custom_prompt || null,
    schedule_time: prefs.schedule_time || null
  }
}];

// Normalize and deduplicate all articles
const userData = $('Loop Users').first().json;
const allItems = $input.all();

let rawArticles = [];

for (const item of allItems) {
  const data = item.json;

  // NewsAPI (returns an object with an 'articles' array)
  if (data.articles && Array.isArray(data.articles)) {
    data.articles.forEach(a => rawArticles.push(a));
  }
  // Guardian (returns an object with response.results)
  else if (data.response && data.response.results && Array.isArray(data.response.results)) {
    data.response.results.forEach(a => rawArticles.push(a));
  }
  // RSS or single article
  else {
    rawArticles.push(data);
  }
}

const normalize = (a) => {
  // NewsAPI
  if (a.source && a.url && a.publishedAt) {
    return {
      title: a.title || 'Untitled',
      description: (a.description || a.content || '').substring(0, 400),
      url: a.url,
      source: a.source?.name || 'NewsAPI',
      publishedAt: a.publishedAt
    };
  }
  // Guardian
  if (a.webUrl || a.webTitle) {
    return {
      title: a.webTitle || 'Untitled',
      description: a.fields?.trailText || '',
      url: a.webUrl,
      source: 'The Guardian',
      publishedAt: a.webPublicationDate || new Date().toISOString()
    };
  }
  // RSS
  if (a.link || a.guid) {
    return {
      title: a.title || 'Untitled',
      description: a.contentSnippet || a.summary || '',
      url: a.link || a.guid,
      source: a.creator || 'BBC News',
      publishedAt: a.pubDate || new Date().toISOString()
    };
  }
  return null;
};

const articles = rawArticles
  .map(a => normalize(a))
  .filter(a => a && a.url && a.title);

// Deduplicate by URL
const seen = new Set();
const unique = articles.filter(a => {
  if (seen.has(a.url)) return false;
  seen.add(a.url);
  return true;
});

// Pre-filter by topics to save tokens
let topics = userData.topics || [];
if (typeof topics === 'string') {
  topics = topics.replace(/^{|}$/g, '').split(',').map(t => t.trim()).filter(Boolean);
}
const filtered = unique.filter(a => {
  if (topics.length === 0) return true;
  const text = (a.title + ' ' + (a.description || '')).toLowerCase();
  return topics.some(t => text.includes(t.toLowerCase()));
});

// Cross-source fact check: confirmation score
const scored = filtered.map(a => {
  const keywords = a.title.split(' ').filter(w => w.length > 4).slice(0, 3);
  const confirmedBy = filtered.filter(b =>
    b.url !== a.url &&
    b.source !== a.source &&
    keywords.some(kw => b.title.toLowerCase().includes(kw.toLowerCase()))
  );
  return { ...a, factCheckScore: confirmedBy.length };
});

// Sort by confirmation score, then limit
const final = scored
  .sort((a, b) => b.factCheckScore - a.factCheckScore)
  .slice(0, 25);

if (final.length === 0) {
  // Always return an item, even empty, so the flow does not break
  return [{ json: { articles: [], userData, message: "No articles found" } }];
}

return final.map(a => ({ json: { ...a, userData } }));

// Aggregate all normalized articles + user context + feedback
const items = $input.all();
if (items.length === 0) return [];

const userData = $('Merge user + prefs').first().json;
let feedbacks = [];
try {
  const feedbackItems = $('Get past feedback').all();
  if (Array.isArray(feedbackItems)) {
    feedbacks = feedbackItems.map(i => i.json?.feedback).filter(Boolean);
  }
} catch (error) {
  feedbacks = [];
}

const articles = items.map(i => ({
  title: i.json.title,
  description: i.json.description,
  url: i.json.url,
  source: i.json.source,
  publishedAt: i.json.publishedAt,
  factCheckScore: i.json.factCheckScore
}));

return [{ json: { userData, articles, feedbacks } }];

// Parse the LLM JSON response
const raw = $json.text || $json.output || '';

// Get the merged data (email, username, num_articles, etc.)
const fusionData = $('Merge user + prefs').first().json;
const limit = parseInt(fusionData.num_articles) || 5;

// Get the ORIGINAL articles from the aggregate node (guaranteed fallback)
const originalArticles = ($('Aggregate for LLM').first().json.articles || []).map(a => ({
  title: a.title,
  summary: a.description || '',
  url: a.url,
  source: a.source
}));

let parsedArticles = [];
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    if (parsed && Array.isArray(parsed.articles) && parsed.articles.length > 0) {
      parsedArticles = parsed.articles;
    }
  }
} catch(e) {
  // Parsing failed, will use fallback
}

// Use the LLM articles if available, otherwise the originals
// In both cases, respect the num_articles limit
const finalArticles = (parsedArticles.length > 0 ? parsedArticles : originalArticles).slice(0, limit);

return [{ json: {
  articles: finalArticles,
  userData: fusionData,
  user_id: fusionData.user_id,
  username: fusionData.username,
  email: fusionData.email
} }];

// Get the current user's prefs
const prefs = $input.item.json;

// No prefs at all: exit cleanly
if (!prefs.user_id) {
  return [{ json: { ...prefs, isMatch: false, debug: 'no prefs found' } }];
}

// Time zone: uses the user's schedule_tz.
// Falls back to Africa/Lagos (UTC+1) when the n8n server runs in another time zone.
let tz = prefs.schedule_tz || 'UTC';
if (tz === 'UTC' || tz === 'America/New_York') {
  tz = 'Africa/Lagos';
}

const nowISO = $('Compute UTC time').first().json.nowISO;
const now = new Date(nowISO);

// Minute-level comparison (HH:mm), thanks to the external cron fired every minute
const fmtHour = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', timeZone: tz, hour12: false });
const fmtMin  = new Intl.DateTimeFormat('en-GB', { minute: '2-digit', timeZone: tz, hour12: false });

const currentHH   = fmtHour.format(now).substring(0, 2).padStart(2, '0');
const currentMM   = fmtMin.format(now).padStart(2, '0');
const currentHHMM = `${currentHH}:${currentMM}`; // e.g. "16:30"

const scheduleHHMM = (prefs.schedule_time || '').substring(0, 5); // e.g. "16:30"

// Set FORCE_SEND = true in tests to bypass this filter
const FORCE_SEND = false;
const isMatch = FORCE_SEND || (currentHHMM === scheduleHHMM);

return [{
  json: {
    ...prefs,
    currentHHMM,
    scheduleHHMM,
    isMatch,
    debug: `tz=${tz} | now=${currentHHMM} vs schedule=${scheduleHHMM} | match=${isMatch}`
  }
}];
